package com.kuzhi.findme.server.data;

import com.kuzhi.findme.common.CompanionKind;
import com.kuzhi.findme.common.CompanionLifecycleState;
import com.kuzhi.findme.common.FindMeUiSettings;
import com.kuzhi.findme.server.data.HomeResidentIndex;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import net.minecraft.nbt.CompoundTag;

public final class CompanionRuntimeIndex {
    private static final CompanionRuntimeIndex EMPTY = new CompanionRuntimeIndex(Map.of(), FindMeUiSettings.defaults().autoPromoteRiddenCompanions());
    private final Map<UUID, Entry> entries;
    private final boolean autoPromoteRiddenCompanions;

    private CompanionRuntimeIndex(Map<UUID, Entry> entries, boolean autoPromoteRiddenCompanions) {
        this.entries = Map.copyOf(entries);
        this.autoPromoteRiddenCompanions = autoPromoteRiddenCompanions;
    }

    public static CompanionRuntimeIndex empty() {
        return EMPTY;
    }

    static CompanionRuntimeIndex fromRoot(CompoundTag root) {
        boolean autoPromote = FindMeUiSettings.load(root == null ? null : root.m_128469_("uiSettings")).autoPromoteRiddenCompanions();
        HomeResidentIndex homeIndex = HomeResidentIndex.fromRoot(root);
        if (homeIndex.entries().isEmpty()) {
            return autoPromote == CompanionRuntimeIndex.EMPTY.autoPromoteRiddenCompanions ? EMPTY : new CompanionRuntimeIndex(Map.of(), autoPromote);
        }
        HashMap<UUID, Entry> result = new HashMap<UUID, Entry>();
        for (HomeResidentIndex.Entry entry : homeIndex.entries()) {
            result.put(entry.uuid(), new Entry(entry.kind(), entry.lifecycleState(), entry.deployed(), entry.stored(), entry.hasHomeAssignment()));
        }
        return new CompanionRuntimeIndex(result, autoPromote);
    }

    public boolean contains(UUID uuid) {
        return uuid != null && this.entries.containsKey(uuid);
    }

    public boolean contains(CompanionKind kind, UUID uuid) {
        Entry entry = uuid == null ? null : this.entries.get(uuid);
        return entry != null && entry.kind == kind;
    }

    public Entry entry(UUID uuid) {
        return uuid == null ? null : this.entries.get(uuid);
    }

    public Set<UUID> uuids() {
        return this.entries.keySet();
    }

    public boolean autoPromoteRiddenCompanions() {
        return this.autoPromoteRiddenCompanions;
    }

    public record Entry(CompanionKind kind, CompanionLifecycleState lifecycleState, boolean deployed, boolean stored, boolean hasHome) {
    }
}

